developerApi.restoreExampleTs:
// send the masked text to any AI service
// detected personal data has been replaced with placeholders
const answer: string = await fetch("https://api.example.com/chat", {
  method: "POST",
  body: JSON.stringify({ prompt: text }),
}).then((r) => r.text())

restore(answer)
// placeholders are replaced with the originals, locally

